func sparklinePoints(history []int) string {
	if len(history) == 0 {
		return "0,40 100,40"
	}
	maxRPS := 10
	for _, v := range history {
		if v > maxRPS {
			maxRPS = v
		}
	}

	points := ""
	step := 100.0 / float64(19)
	if len(history) < 20 {
		if len(history) > 1 {
			step = 100.0 / float64(len(history)-1)
		} else {
			step = 0
		}
	}

	if step == 0 {
		y := 40 - (float64(history[0])/float64(maxRPS))*35
		return fmt.Sprintf("0,%f 100,%f", y, y)
	}

	for i, v := range history {
		x := float64(i) * step
		y := 40 - (float64(v)/float64(maxRPS))*35
		points += fmt.Sprintf("%.1f,%.1f ", x, y)
	}
	return points
}

func getUptimeStr(createdAt time.Time, format string) string {
	sec := 60.0 - time.Since(createdAt).Seconds()
	if sec <= 0 {
		return "-"
	}
	if format == "tooltip" {
		return fmt.Sprintf("%.0fs", sec)
	}
	return fmt.Sprintf("%.0fs up", sec)
}

